def pre(xs):
    return True

def post(xs, result):
    n = len(xs)
    total = sum(xs)
    if n == 0:
        expected = True
    else:
        # all subset sums of the first n-1 elements
        sums = [0]
        for i in range(n - 1):
            cur = list(sums)
            for s in cur:
                sums.append(s + xs[i])
        expected = False
        x = xs[n - 1]
        for s in sums:
            # last element goes to the other group, or to this group
            if 2 * s == total or 2 * (s + x) == total:
                expected = True
    return result == expected
